steps.solution:
def average(scores):
    if not scores:
        return 0.0
    return round(sum(scores) / len(scores), 1)


def letter(avg):
    if avg >= 90:
        return "A"
    if avg >= 80:
        return "B"
    if avg >= 70:
        return "C"
    if avg >= 60:
        return "D"
    return "F"


def summary(book):
    result = {}
    for name, scores in book.items():
        avg = average(scores)
        result[name] = (avg, letter(avg))
    return result


def report(book):
    rows = sorted(summary(book).items(), key=lambda item: (-item[1][0], item[0]))
    return [f"{i}. {name} {avg} {grade}" for i, (name, (avg, grade)) in enumerate(rows, start=1)]
